{
  "title": "Attention Is All You Need",
  "slides": [
    {
      "title": "The Problem with Recurrent Models",
      "bullets": [
        "Recurrent models process sequences sequentially.",
        "This prevents parallelization within training examples.",
        "Long sequences hit memory constraints quickly."
      ]
    },
    {
      "title": "Introducing the Transformer Architecture",
      "bullets": [
        "We propose a new simple network architecture.",
        "It relies solely on attention mechanisms.",
        "Recurrence and convolutions are entirely removed."
      ]
    },
    {
      "title": "Encoder and Decoder Structure",
      "bullets": [
        "Stacks of N=6 identical layers for both encoder and decoder.",
        "Multi-head self-attention connects all positions.",
        "Residual connections and layer normalization are used."
      ]
    },
    {
      "title": "Why Self-Attention Wins",
      "bullets": [
        "Self-attention requires constant sequential operations.",
        "Recurrent layers need O(n) sequential operations.",
        "Shorter paths help learn long-range dependencies."
      ]
    },
    {
      "title": "Training Efficiency and Hardware",
      "bullets": [
        "Trained on 8 NVIDIA P100 GPUs.",
        "Big model took 3.5 days to train.",
        "Significantly less time than previous best models."
      ]
    },
    {
      "title": "State-of-the-Art Translation Results",
      "bullets": [
        "Achieved 28.4 BLEU on English-to-German.",
        "Improved over existing best results by over 2 BLEU.",
        "Established new single-model state for English-to-French."
      ]
    },
    {
      "title": "Generalization to Other Tasks",
      "bullets": [
        "Transformer generalizes well beyond translation.",
        "Successfully applied to English constituency parsing.",
        "Works with both large and limited training data."
      ]
    }
  ]
}
